 "content": "from collections import Counter


def transform(grid):
    out = [row[:] for row in grid]
    width = len(grid[0])
    full_rows = [row[0] for row in grid if len(set(row)) == 1]
    # The repeated full-width color is the background; the exceptional
    # full-width color identifies the stripe color to preserve.
    counts = Counter(full_rows)
    foreground = min(counts, key=counts.get)
    for i, row in enumerate(grid):
        if len(set(row)) == 2 and row.count(foreground) == width // 2:
            for j, value in enumerate(row):
                if value != foreground:
                    out[i][j] = 1
    return out
